/**
 * Decodes octets to characters using the UTF-8 decoding and appends the characters to a StringBuffer.
 * @return the index to the next unchecked character in the string to decode
 */
private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int start = i;
    int length = bb.remaining();
    while (i < start + length) {
        byte b = bb.get(i);
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (i + 1 < start + length) {
                int value = ((b & 0x1F) << 6) | (bb.get(i + 1) & 0x3F);
                sb.append((char) value);
                i += 2;
            } else {
                // Invalid sequence
                i++;
            }
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (i + 2 < start + length) {
                int value = ((b & 0x0F) << 12) | ((bb.get(i + 1) & 0x3F) << 6) | (bb.get(i + 2) & 0x3F);
                sb.append((char) value);
                i += 3;
            } else {
                // Invalid sequence
                i++;
            }
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            if (i + 3 < start + length) {
                int value = ((b & 0x07) << 18) | ((bb.get(i + 1) & 0x3F) << 12) | ((bb.get(i + 2) & 0x3F) << 6) | (bb.get(i + 3) & 0x3F);
                sb.appendCodePoint(value);
                i += 4;
            } else {
                // Invalid sequence
                i++;
            }
        } else {
            // Invalid sequence
            i++;
        }
    }
    return i;
}
