public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current index's mappings for the given table
    Mappings currentIndexMappings = getMappingsFromCurrentIndex(tableName);

    // Remove the _source configuration from both mappings to avoid update conflicts
    currentIndexMappings.remove("_source");
    mappings.remove("_source");

    // Find the fields that exist in the current index but not in the input mappings
    Set<String> diffFields = new HashSet<>(currentIndexMappings.getKeys());
    diffFields.removeAll(mappings.getKeys());

    // Create a new Mappings object to store the differences
    Mappings diffMappings = new Mappings();

    // Add the differing fields to the diffMappings object
    for (String field : diffFields) {
        diffMappings.put(field, currentIndexMappings.get(field));
    }

    return diffMappings;
}
