 */
protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = 10 * 60 * 1000; // 10 minutes in milliseconds

    while (start < end) {
        long potentialEnd = Math.min(start + fetchDataDuration, end);
        timeRanges.add(new TimeRange(start, potentialEnd));
        start = potentialEnd;
    }

    return timeRanges;
}
