static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = (timeBucket / 10000) * 10000; // Extract the year part
    long month = (timeBucket / 100) % 100; // Extract the month part
    long day = timeBucket % 100; // Extract the day part

    // Adjust the day according to the dayStep
    int adjustedDay = (int) Math.floor(day / dayStep) * dayStep + dayStep - 1;

    // Ensure the adjusted day is within the range of the month
    if (adjustedDay > 31) {
        month += 1;
        adjustedDay = 1;
    }

    return year + month * 100 + adjustedDay;
}
