public static String findAndSubst(String key, Properties props) {
    // Retrieve the value corresponding to the key from the properties
    String value = props.getProperty(key);

    if (value != null) {
        // Perform variable substitution in the value
        value = substVars(value, props);
    }

    return value;
}

/**
 * Perform variable substitution in the given string using the provided properties.
 */
private static String substVars(String s, Properties props) {
    StringBuilder buf = new StringBuilder();
    int off = 0;
    while (off < s.length()) {
        if (s.indexOf("${", off) == off) {
            int end = s.indexOf("}", off + 2);
            if (end == -1) {
                break;
            }
            String expr = s.substring(off + 2, end);
            String subst = props.getProperty(expr);
            if (subst != null) {
                buf.append(subst);
            } else {
                buf.append("${").append(expr).append("}");
            }
            off = end + 1;
        } else {
            buf.append(s.charAt(off++));
        }
    }
    return buf.toString();
}
