public class Accumulator {
    private Map<String, Long> cache;

    public Accumulator() {
        this.cache = new HashMap<>();
    }

    public void valueAccumulation(String key, Long value) {
        if (cache.containsKey(key)) {
            cache.put(key, cache.get(key) + value);
        } else {
            cache.put(key, value);
        }
    }

    public Long getValue(String key) {
        return cache.getOrDefault(key, 0L);
    }

    public static void main(String[] args) {
        Accumulator accumulator = new Accumulator();
        accumulator.valueAccumulation("testKey", 10L);
        accumulator.valueAccumulation("testKey", 20L);
        System.out.println(accumulator.getValue("testKey")); // Output: 30
    }
