/**
 * Clear and fill the buffer of this {@code ClassFileBuffer} with the supplied byte stream. The read pointer is reset to the start of the byte array.
 */
public void readFrom(final InputStream in) throws IOException {
    clear();
    byte[] buffer = new byte[1024];
    int bytesRead;
    while ((bytesRead = in.read(buffer)) != -1) {
        int offset = 0;
        while (offset < bytesRead) {
            if (buffer.length - offset < bytesRead - offset) {
                // Buffer is too small, resize it
                byte[] newBuffer = new byte[buffer.length * 2];
                System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
                buffer = newBuffer;
            }
            System.arraycopy(buffer, offset, this.buffer, this.buffer.length - this.position, bytesRead - offset);
            offset += bytesRead - offset;
        }
        this.position += bytesRead;
    }
    resetReadPointer();
}
