public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int capacity = desiredCapacity;
    while (!isPrime(capacity)) {
        capacity++;
    }
    if (desiredCapacity >= 1000 && capacity - desiredCapacity > 0.11 * desiredCapacity) {
        do {
            capacity--;
        } while (!isPrime(capacity) && capacity - desiredCapacity > 0.11 * desiredCapacity);
    }
    return capacity;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number == 2) {
        return true;
    }
    if (number % 2 == 0) {
        return false;
    }
    for (int i = 3; i <= Math.sqrt(number); i += 2) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}
