private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Integer, Integer>> localSeparatorList = new ArrayList<>();
        Node startNode = edge.getStartNode();
        Node endNode = edge.getEndNode();
        for (Node neighbor : graph.getNeighbors(startNode)) {
            if (neighbor != endNode) {
                List<Pair<Integer, Integer>> separatorList = findMinimalSeparator(neighbor, endNode, graph);
                localSeparatorList.addAll(separatorList);
            }
        }
        for (Node neighbor : graph.getNeighbors(endNode)) {
            if (neighbor != startNode) {
                List<Pair<Integer, Integer>> separatorList = findMinimalSeparator(neighbor, startNode, graph);
                localSeparatorList.addAll(separatorList);
            }
        }
        globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
    }
    return globalSeparatorList;
}

private List<Pair<Integer, Integer>> findMinimalSeparator(Node node1, Node node2, Graph graph) {
    Set<Node> node1Neighbors = graph.getNeighbors(node1);
    Set<Node> node2Neighbors = graph.getNeighbors(node2);
    Set<Node> intersection = new HashSet<>(node1Neighbors);
    intersection.retainAll(node2Neighbors);
    if (intersection.size() <= 2) {
        return new ArrayList<>();
    }
    List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
    for (Node neighbor : intersection) {
        if (neighbor != node1 && neighbor != node2) {
