private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Iterate over all pairs of vertices in the set
    for (V u : vertices) {
        for (V v : vertices) {
            // If u and v are the same, skip to the next iteration
            if (u.equals(v)) {
                continue;
            }
            // Check if there is an edge between u and v
            if (!graph.containsEdge(u, v)) {
                // If no edge exists, the subgraph is not a clique
                return false;
            }
        }
    }
    // If all pairs have an edge, the subgraph is a clique
    return true;
}
