public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        LineParser parser = new LineParser(line);
        long timestamp = parser.getTimestamp();
        if (isTimestampInRange(timestamp, timeRanges)) {
            ThreadSnapshot snapshot = parser.parseThreadSnapshot();
            snapshots.add(snapshot);
        }
    }
    reader.close();
    return snapshots;
}

private static boolean isTimestampInRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (range.isInRange(timestamp)) {
            return true;
        }
    }
    return false;
}
